// ===== EINZIGE STELLE MIT KONFIG =====
const MCP_URL = 'https://DEINE-MCP-URL/mcp'; // claude.ai -> Settings -> Connectors -> SellerBoard

const inp = $input.first().json;
if (!inp.tool) throw new Error('Feld "tool" fehlt im Aufruf');

return [{ json: {
  mcpUrl: MCP_URL,
  tool: inp.tool,
  arguments: inp.arguments || {},
  maxAttempts: inp.maxAttempts || 6,
  waitSeconds: inp.waitSeconds || 8
}}];

// Session-Id merken (stateful Server); bleibt leer bei stateless Servern.
const cfg = $('Vorbereiten').first().json;
const r = $input.first().json;
const headers = r.headers || {};
if ((r.statusCode || 0) >= 400) {
  throw new Error(`MCP initialize fehlgeschlagen: HTTP ${r.statusCode} - ${String(r.body).slice(0, 300)}`);
}
return [{ json: { ...cfg, sessionId: headers['mcp-session-id'] || '' } }];

// MCP-Antwort auspacken. Body ist entweder JSON oder SSE ("data: {...}"-Zeilen).
const cfg = $('Session').first().json;
const r = $input.first().json;
const attempt = $runIndex + 1;

let body = String(r.body ?? '').trim();
let rpc = {};
if (body.startsWith('{')) {
  rpc = JSON.parse(body);
} else {
  const lines = body.split('\n').filter(l => l.startsWith('data:'));
  for (const l of lines) {
    try {
      const j = JSON.parse(l.slice(5).trim());
      if (j.result || j.error) rpc = j;
    } catch (e) {}
  }
}

const httpError = (r.statusCode || 0) >= 400 ? `HTTP ${r.statusCode}` : null;
const rpcError = rpc.error ? (rpc.error.message || JSON.stringify(rpc.error)) : null;

// Tool-Ergebnis: Text-Content = kurze Zusammenfassung + JSON-Block
let payload = rpc?.result?.structuredContent ?? null;
if (!payload) {
  const text = (rpc?.result?.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  const i = text.indexOf('{');
  if (i >= 0) { try { payload = JSON.parse(text.slice(i)); } catch (e) { payload = { raw: text }; } }
  else payload = { raw: text };
}
const toolError = rpc?.result?.isError ? String(payload?.raw ?? JSON.stringify(payload)).slice(0, 500) : null;

const preparing = payload?.status === 'preparing';
const retry = preparing && attempt < cfg.maxAttempts;

return [{ json: {
  tool: cfg.tool,
  arguments: cfg.arguments,
  attempt,
  preparing,
  retry,
  waitSeconds: cfg.waitSeconds,
  ok: !httpError && !rpcError && !toolError && !preparing,
  error: httpError || rpcError || toolError || (preparing ? 'preparing (Timeout nach ' + attempt + ' Versuchen)' : null),
  payload
}}];

// Ergebnis an den aufrufenden Workflow zurueckgeben
const r = $input.first().json;
return [{ json: { ok: r.ok, tool: r.tool, arguments: r.arguments, attempts: r.attempt, error: r.error, payload: r.payload } }];
